NAME = 'UkrOgienko: Українська Біблія. Переклад Івана Огієнка.'
BOOK = 'Nahum'

CHAPTERS = {
    1: {
        1: 'Пророцтво на Ніневію. Книга видіння елкошейця Наума.',
        2: "„Палки́й Бог, і мсти́вий Госпо́дь, Господь мстивий та лютий, — Господь мстивий до тих, хто Його ненавидить, і пам'ятає про кривду Своїх ворогів.",
        3: 'Господь довготерпели́вий і великої поту́ги, та очистити винного — Він не очистить. Господь — у бурі та в ви́хрі доро́га Його, а хмара — від стіп Його ку́рява.',
        4: "Як загні́вається Він на море, то сушить його, і всі рі́ки висушує, в'яне Баша́н та Карме́л, і в'яне та квітка Ліва́ну.",
        5: 'Гори тремтять перед Ним, а підгі́рки топні́ють, перед обличчям Його трясеться земля та вселе́нна, та всі її ме́шканці.',
        6: "Хто встоїть перед гнівом Його́, і хто стане у по́лум'ї люті Його? Його шал виливається, мов той огонь, і розпада́ються скелі від Нього!",
        7: 'Добрий Господь, пристано́вище Він у день у́тиску, і знає Він тих, хто на Нього наді́ється!',
        8: 'Але в зливі нава́льній Він зробить кінця́ між Його заколо́тниками, і ворогів зажене́ у темно́ту.',
        9: 'Що ви ду́маєте проти Господа? Бо Він зробить кінця́, — не поста́не два ра́зи наси́льство.',
        10: 'Бо вони переплу́тані, наче той те́рен, і повпива́лись, немов би вином, — вони будуть пожерті зовсі́м, мов солома суха!',
        11: 'З тебе вийшов заду́муючий проти Господа лихо, радник нікче́мний.',
        12: 'Так говорить Госпо́дь: Хоч були б найсильніші і дуже числе́нні, та пости́нані будуть вони, та й мину́ться! І хоч Я тебе мучив, та мучити більше тебе вже не бу́ду!',
        13: 'А тепер Я злама́ю ярмо́ його, яке на тобі, і пу́та твої позрива́ю.',
        14: 'І накаже на тебе, Ашшу́ре, Господь: Більш не буде вже сі́ятися з твого йме́ння! З дому бога твого́ Я бовва́на та і́дола ви́тну, зроблю́ тобі гро́ба із них, бо ти став легкова́жений.',
    },
    2: {
        1: 'Ось на горах ноги́ благові́сника, що звіщає про мир: Святкуй, Юдо, свята свої, виконуй прися́ги свої, бо більше не буде нікче́мний ходи́ти по тобі, — він ви́тятий ввесь!',
        2: 'На тебе йде розпоро́шувач, — тверди́ні свої стережи́, вигляда́й на дорогу, зміцня́й свої сте́гна, мі́цно скріпи свою поту́гу,',
        3: 'бо ве́рне Господь ве́лич Якова, як ве́лич Ізраїля, що їхні спустоши́телі поруйнува́ли, і понищили їхні виноградні галу́зки.',
        4: 'Щит хоробрих його зачерво́нений, вояки́ в кармази́ні; блищить сталь у день зброє́ння їхнього на колесни́цях, хвилю́ються ра́тища.',
        5: "Колесни́ці шалено по вулицях мчать, по майда́нах гурко́чуть, їхній вид — немов по́лум'я те смолоски́пів, літають вони, як ті бли́скавки.",
        6: 'Він згадає шляхе́тних своїх, та спіткну́ться вони у ході́ своїй; вони поспішають на мури її, і поста́влена міцно буді́вля обло́ги.',
        7: 'Брами річо́к відчиня́ються, а пала́та руйнується.',
        8: 'І постано́влено: буде ого́лена, відведе́ться в поло́н, а рабині її голоси́тимуть, мов ті голу́бки, що ворку́ють на пе́рсах своїх.',
        9: 'І Ніневі́я — як са́джавка во́дна, що во́ди її відплива́ють. „Стійте, стійте!“Та немає ніко́го, хто б їх заверну́в!',
        10: 'Розграбо́вуйте срі́бло, розграбо́вуйте золото, — немає кінця нагото́вленому, багатству кошто́вних рече́й.',
        11: 'Зни́щення та зруйнува́ння й спусто́шення буде. І серце розто́питься, і но́ги дрижа́тимуть, і ко́рчі по кри́жах усіх, а обличчя їх всіх на черво́но розпа́ляться.',
        12: 'Де лего́вище ле́вів, і для левчукі́в пасови́ще, що там ходив лев та леви́ця, та левеня́, — і ніхто не лякав?',
        13: 'Лев грабував для своїх молодят і душив для леви́ць своїх він, і пече́ри свої перепо́внював здо́биччю, а лі́гва свої — награбо́ваним.',
        14: 'Ось Я проти тебе, — говорить Господь Савао́т, — і попалю́ серед диму твої коле́сни́ці, а твоїх левчукі́в поїсть меч, і повитина́ю з землі грабува́ння твої, і вже не почується голос твого посла.',
    },
    3: {
        1: 'Горе місту цьому кровоже́рному, воно все неправда, воно повне наси́лля, грабі́ж не виходить із нього!',
        2: 'Чути свист батога́, гу́ркіт ко́леса, і чвал ко́ней, і колесни́чна гурко́тнява,',
        3: "і гін верхівця́, і по́лум'я меча́, і блиск ра́тища, і багато побитих, і мертвих велике число́, і тру́пу немає кінця́, і спотика́тимуться об їхній труп, —",
        4: 'це за многоту́ блудоді́йства розпу́сниці, прива́бно ласка́вої, впра́вної в ча́рах, що наро́ди за блуд свій вона продавала, а ро́ди — за ча́ри свої.',
        5: 'Ось Я проти тебе, — говорить Госпо́дь Савао́т, — і подо́лка твого підійму́ на обличчя твоє, і покажу́ Я твій сором наро́дам, а ца́рствам — твій стид!',
        6: 'І кину на тебе оги́ди, і пого́рдженою вчиню́ Я тебе, і зроблю́ Я тебе, мов позо́рище!',
        7: 'І станеться, — кожен, хто вгле́дить тебе, від тебе втече та й прокаже: „Пограбо́вана Ніневі́я!“Хто ви́словить їй співчуття́? Звідки буду шукати тобі потіши́телів?',
        8: 'Чи краща ти від Но-Амона, що сидить серед рік, — вода коло нього, що вал його — море, від моря — його мур?',
        9: 'Етіо́пія — сила його, і Єгипет, і не має кінця́. Пут та ліві́йці були тобі в по́міч, —',
        10: 'та й він на вигна́ння пішов, у поло́н. А діти його порозби́вані на роздоріжжі всіх вулиць, і кидали же́реб про славних його, й всі вельможі його у кайда́ни закуті.',
        11: "Уп'єшся і ти, будеш схо́вана, тверди́ні від ворога будеш шукати і ти!",
        12: 'Всі форте́ці твої, — мов ті фіґи з доспі́лими о́вочами: коли затрясу́ться, то падають в у́ста того, хто їх їсть.',
        13: 'Ось наро́д твій — немов ті жінки́ серед тебе: вони повідчиня́ють твоїм ворогам брами кра́ю твого, огонь пожере́ твої за́суви.',
        14: 'Води́ на облогу собі набери́, тверди́ні свої позміцня́й, увійди до боло́та та в глині топчи́сь, форму на цеглу візьми́ міцно в ру́ку.',
        15: "Там огонь тебе з'їсть, посіче́ тебе меч, пожеру́ть тебе, наче та гу́сінь. Стань числе́нна, як гусінь, стань числе́нна, немов сарана́, —",
        16: 'понамно́жуй купці́в своїх більше від зі́рок небесних, — але гусінь та знищить тебе й полети́ть!',
        17: 'Вельможні твої — немов та сарана́, гетьма́ни твої — мов мошва́, що гнізди́ться по сті́нах в день хо́лоду, але сонце засвітить — і вони помандру́ють, і не пі́знане буде те місце, де вони пробува́ли.',
        18: 'Твої па́стирі, ца́рю асирійський, посну́ли, лежать вельмо́жі твої, твій наро́д розпоро́шивсь по го́рах, — і немає кому́ позбира́ти його́.',
        19: 'Нема ліку для лиха твого́, рана твоя невиго́йна! Всі, що звістку про тебе почують, запле́щуть у долоні на тебе, — бо над ким твоє зло не ходило пості́йно?“',
    },
}
